package com.jobsphere.service;
import org.springframework.stereotype.Service; import java.time.Instant; import java.util.UUID; import java.util.concurrent.ConcurrentHashMap; import java.util.concurrent.ConcurrentMap;
@Service public class TokenService { private record Session(Long userId,Instant expires){ } private final ConcurrentMap<String,Session> sessions=new ConcurrentHashMap<>(); private static final long TTL_SECONDS=8*60*60; public String issue(Long id){String t=UUID.randomUUID().toString();sessions.put(t,new Session(id,Instant.now().plusSeconds(TTL_SECONDS)));return t;} public Long user(String token){if(token==null||token.isBlank())return null;Session s=sessions.get(token);if(s==null)return null;if(s.expires().isBefore(Instant.now())){sessions.remove(token);return null;}return s.userId();} public void revoke(String token){if(token!=null)sessions.remove(token);} }
